typedef void (*ErrorCallback)(int code, const char* msg);

// Function accepting a callback pointer
void process_data(int* data, size_t n, ErrorCallback on_fail);

// Declaration of a variable to hold the pointer
ErrorCallback handler_ptr;

// Invocation
if (error) {
    handler_ptr(404, "Not Found");
}

// --- Callback within a Structure (Contextual) ---
typedef int (*FilterFunc)(void* element, void* context);

struct FilterConfig {
    FilterFunc predicate;
    void* context_data;
};

// Usage:
struct FilterConfig cfg = {
    .predicate = &my_custom_filter,
    .context_data = &global_settings
};

// --- Dispatch Table (Array of Function Pointers) ---
typedef float (*MathOp)(float a, float b);
float op_add(float a, float b) { return a + b; }

// Array definition
MathOp operation_vtable[] = {
    op_add,
    /* op_sub, ... */
};

float result = operation_vtable[0](10.0, 5.0);
